"""Compute the ordinal rank (longest accessibility chain) of every world
in a finite Gödel-Löb frame, and verify it equals the longest-chain length."""
from __future__ import annotations
from typing import Dict, List, Set, Tuple, Iterable

def succ_map(worlds: List[int], edges: Iterable[Tuple[int, int]]) -> Dict[int, Set[int]]:
    s: Dict[int, Set[int]] = {w: set() for w in worlds}
    for a, b in edges:
        s[a].add(b)
    return s

def rank(w: int, succ: Dict[int, Set[int]], memo: Dict[int, int]) -> int:
    if w in memo:
        return memo[w]
    if not succ[w]:
        memo[w] = 0
        return 0
    memo[w] = 1 + max(rank(v, succ, memo) for v in succ[w])
    return memo[w]

if __name__ == "__main__":
    worlds = list(range(6))
    # transitive, irreflexive: n sees all m < n  -> rank(n) = n
    edges = [(a, b) for a in worlds for b in worlds if a > b]
    succ = succ_map(worlds, edges)
    memo: Dict[int, int] = {}
    for w in worlds:
        r = rank(w, succ, memo)
        print(f"rank({w}) = {r}")
        assert r == w
    print("ordinal rank equals longest-chain length.  OK")

"""Verify the box/diamond rank stratification on a finite GL frame:
box^k(empty) = {rank < k}  and  diamond^k(univ) = {rank >= k}, exact complements."""
from __future__ import annotations
from typing import Callable, Dict, List, Set, Tuple, Iterable

def closure(worlds: List[str], base: Iterable[Tuple[str, str]]) -> Dict[str, Set[str]]:
    reach: Dict[str, Set[str]] = {w: set() for w in worlds}
    for a, b in base:
        reach[a].add(b)
    changed = True
    while changed:
        changed = False
        for a in worlds:
            new = set().union(*(reach[b] for b in reach[a])) if reach[a] else set()
            if not new <= reach[a]:
                reach[a] |= new
                changed = True
    return reach

def rank_all(worlds: List[str], succ: Dict[str, Set[str]]) -> Dict[str, int]:
    memo: Dict[str, int] = {}
    def r(w: str) -> int:
        if w in memo: return memo[w]
        memo[w] = (1 + max((r(v) for v in succ[w]), default=-1))
        return memo[w]
    return {w: r(w) for w in worlds}

if __name__ == "__main__":
    worlds = ["a", "b", "c", "d", "e"]
    base = [("a","b"),("a","c"),("b","d"),("c","d"),("c","e")]
    succ = closure(worlds, base)
    ranks = rank_all(worlds, succ)
    box: Callable[[Set[str]], Set[str]] = lambda S: {w for w in worlds if succ[w] <= S}
    dia: Callable[[Set[str]], Set[str]] = lambda S: {w for w in worlds if succ[w] & S}
    univ, empty = set(worlds), set()
    for k in range(max(ranks.values()) + 3):
        bk, dk = empty, univ
        for _ in range(k):
            bk, dk = box(bk), dia(dk)
        assert bk == {w for w in worlds if ranks[w] < k}
        assert dk == {w for w in worlds if ranks[w] >= k}
        assert bk == univ - dk
        print(f"k={k}: box^k(empty)={sorted(bk)}  diamond^k(univ)={sorted(dk)}")
    print("stratification + exact complement verified.  OK")

"""Verify rank(a,b) = min(rank a, rank b) in the synchronized product of two
GL frames (the categorical product where a step advances both coordinates)."""
from __future__ import annotations
from itertools import product
from typing import Dict, List, Set, Tuple

def chain(m: int) -> Tuple[List[int], Dict[int, Set[int]]]:
    ws = list(range(m))
    succ = {a: {b for b in ws if a > b} for a in ws}
    return ws, succ

def ranks(ws: List, succ: Dict) -> Dict:
    memo: Dict = {}
    def r(w):
        if w in memo: return memo[w]
        memo[w] = 1 + max((r(v) for v in succ[w]), default=-1)
        return memo[w]
    return {w: r(w) for w in ws}

if __name__ == "__main__":
    Fw, Fs = chain(3); Gw, Gs = chain(4)
    rF, rG = ranks(Fw, Fs), ranks(Gw, Gs)
    Pw = list(product(Fw, Gw))
    Ps = {(a, b): {(c, d) for c in Fs[a] for d in Gs[b]} for (a, b) in Pw}
    rP = ranks(Pw, Ps)
    for (a, b) in Pw:
        assert rP[(a, b)] == min(rF[a], rG[b])
        print(f"rank({a},{b}) = {rP[(a,b)]} = min({rF[a]},{rG[b]})")
    print("product rank = pointwise minimum.  OK")

"""Verify polymodal antitonicity: nested relations R0 superset R1 superset R2
give non-increasing ranks rank_0(w) >= rank_1(w) >= rank_2(w)."""
from __future__ import annotations
from typing import Dict, List, Set

def level_ranks(worlds: List[int], min_gap: int) -> Dict[int, int]:
    # R_n keeps strict steps of size >= min_gap (already transitive on a chain)
    succ = {a: {b for b in worlds if a - b >= min_gap} for a in worlds}
    memo: Dict[int, int] = {}
    def r(w: int) -> int:
        if w in memo: return memo[w]
        memo[w] = 1 + max((r(v) for v in succ[w]), default=-1)
        return memo[w]
    return {w: r(w) for w in worlds}

if __name__ == "__main__":
    worlds = list(range(5))
    R = {0: level_ranks(worlds, 1), 1: level_ranks(worlds, 2), 2: level_ranks(worlds, 3)}
    for w in worlds:
        row = [R[n][w] for n in (0, 1, 2)]
        assert row[0] >= row[1] >= row[2]
        print(f"world {w}: rank_0={row[0]} rank_1={row[1]} rank_2={row[2]}")
    print("rank is antitone in the modality index.  OK")

