function STRATIFY(worlds, succ, k):
    box := empty;  dia := worlds
    repeat k times:
        box := { w | succ(w) subset of box }
        dia := { w | succ(w) intersects dia }
    return (box, dia)   # = ({rank<k}, {rank>=k})

function PRODUCT_RANKS(Fw,Fsucc, Gw,Gsucc):
    Pw := { (a,b) | a in Fw, b in Gw }
    Psucc(a,b) := { (c,d) | c in Fsucc(a), d in Gsucc(b) }
    return RANK over (Pw, Psucc)   # equals min(rank a, rank b)

